INSERT INTO "public"."series" ("id", "category_id", "code", "name", "description", "image_url", "status", "sort_order", "created_at", "updated_at", "color") VALUES ('771140b1-dabf-4625-adc0-957ab5915c04', '53ac016a-ed93-4040-998f-97fe48d6a06b', 'DITTO', 'DITTO迪圖 悅刻1/4代通配', '【Ditto 一代陶瓷煙彈】\n大牌同款高密度陶瓷芯技術\n穩定良率 × 極致口味表達\n一盒三顆入，18款全新口味\n\n熱銷口味搶先看\n\n戀人草莓 Berry Dream｜涼度 4酸甜初戀滋味，微涼清爽\n\n狂野魔爪 Wild Claw｜涼度 4能量爆發，提神醒腦首選\n\n茉莉清韻 Jasmine Breeze｜涼度 5清新花香，涼感加倍\n\n藍莓雪沙 Bursting Berry｜涼度 4冰涼莓果，夏日必備\n\n勁涼青箭 Mint Drops｜涼度 5超強冰感，瞬間清爽\n\n東京淡菸 Tokyo Light｜涼度 0經典菸草，溫和順喉\n\n南極薄荷 Extreme Menthol｜涼度 5極致冰涼，涼感爆表\n\n美粒甜橘 Frozen Citrus｜涼度 3清新柑橘，微涼順口\n\n南洋冰茶 Tropical Chill｜涼度 4異國風情，冰涼解渴\n\n脆甜青蘋 Crispy Apple｜涼度 3青蘋脆爽，清新怡人\n\n仲夏西瓜 Summer Melon｜涼度 4夏日西瓜，冰涼多汁\n\n糖蜜柚綠 Sugar Grapefruit｜涼度 3柚香清甜，回味無窮\n\n翠檸芭樂 Guava Sour｜涼度 3熱帶果香，酸甜誘人\n\n蜜桃甜心 Peachy Pop｜涼度 4水蜜桃香，冰感甜蜜\n\n金桃烏龍 Oolong Peach｜涼度 4茶香果韻，層次豐富\n\n芒芒雪泥 Mango Slush｜涼度 4芒果冰沙，濃郁香甜\n\n冰晶百香果 Passion Spark｜涼度 3百香清爽，酸甜迷人\n\n葡萄果粒 Iced Grapelets｜涼度 3冰鎮葡萄，果香飽滿', 'https://qwovavytryvgchcowjof.supabase.co/storage/v1/object/public/products/series/771140b1-dabf-4625-adc0-957ab5915c04/main.jpg', 'active', '0', '2026-01-09 19:20:48.660212+00', '2026-01-10 19:16:30.976222+00', '#A78BFA');
